(function(){'use strict';const T=MythosPassives,M=MythosStudy,$=id=>document.getElementById(id),KEY='mythos.passive.study.v1';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const shapes={sword:'M-7-9-4-8 7 5 5 7-8-4Z M2 8 8 2 M5 7 10 12',heart:'M0 9C-2 6-12-1-8-7-5-11-1-9 0-6 1-9 5-11 8-7 12-1 2 6 0 9Z',moon:'M6-10C-10-9-11 8 3 11 7 11 10 8 11 5-4 9-7-6 6-10Z',flame:'M0-12C7-5 0-4 6 1L9-3C16 8 1 15-5 8-12 1-2-2 0-12Z',bow:'M-8-11C12-10 12 10-8 11 M-8-11-1 0-8 11 M-11 0H12 M8-4 12 0 8 4',vial:'M-4-12H4 M-3-12V-5L-9 6Q-10 11-4 11H4Q10 11 9 6L3-5V-12 M-7 3H7',shield:'M0-12 10-8 9 3Q6 10 0 13-6 10-9 3L-10-8Z M0-6V7 M-6 0H6',rune:'M0-12 9 0 0 12-9 0Z M0-7V7 M-5 0H5'};
function glyph(f,scale=1){return '<path d="'+shapes[f.icon]+'" transform="scale('+scale+')"/>';}
function difference(a,b){return a.size!==b.size||[...a].some(id=>!b.has(id));}
class PassiveStudy{
 constructor(){this.level=25;this.applied=new Set();this.draft=new Set();this.selected='root';this.tab='node';this.matches=new Set();this.filtered=false;this.route=[];this.drag=null;this.storage=true;this.view={x:-1100,y:-740,w:2200,h:1480};this.nodes=new Map();this.lines=[];this.load();this.mount();this.bind();this.paint();this.center();}
 load(){try{const raw=localStorage.getItem(KEY);if(raw){const loaded=M.validateSave(JSON.parse(raw));this.level=loaded.level;this.applied=loaded.nodes;this.draft=new Set(loaded.nodes);}}catch{this.storage=false;} }
 save(){try{localStorage.setItem(KEY,JSON.stringify(M.snapshot(this.level,this.applied)));this.storage=true;$('saveState').textContent='Estudo salvo neste navegador';return true;}catch{this.storage=false;$('saveState').textContent='Use Exportar para guardar o estudo';return false;}}
 mount(){
  $('testLevel').value=String(this.level);$('catalogSize').textContent=(T.nodes.length-1)+' passivas · '+T.groups.length+' grupos · '+Object.keys(T.MODS).length+' modificadores';
  for(const f of T.families){const opt=document.createElement('option');opt.value=f.key;opt.textContent=f.name;$('family').append(opt);}
  $('mapOrnaments').innerHTML=T.groups.map(g=>'<circle class="group-orbit" cx="'+g.x+'" cy="'+g.y+'" r="'+g.radius+'"/>').join('')+T.families.map(f=>{const a=f.angle+Math.PI/10;return '<text class="affinity-label" x="'+Math.cos(a)*1860+'" y="'+Math.sin(a)*1860+'">'+esc(f.name.toLocaleUpperCase('pt-BR'))+'</text>';}).join('');
  $('connections').innerHTML=T.edges.map(([a,b],i)=>{const n=T.index.get(a),m=T.index.get(b);return '<path class="connection" data-edge="'+i+'" d="M'+n.x+' '+n.y+'L'+m.x+' '+m.y+'"/>';}).join('');
  $('passiveNodes').innerHTML=T.nodes.filter(n=>n.id!=='root').map(n=>{const f=T.families.find(f=>f.key===n.family),r=n.type==='travel'?7:n.type==='small'?11:n.type==='notable'?22:29;return '<g class="passive" data-node="'+n.id+'" transform="translate('+n.x+' '+n.y+')" style="--color:'+f.color+'" role="button" tabindex="-1" aria-label="'+esc(n.title+': '+T.lines(n).join('; '))+'"><circle class="hit" r="'+Math.max(23,r+5)+'"/>'+(n.type==='keystone'?'<path class="node-ring" d="M0-32 30-10 19 26-19 26-30-10Z"/>':'<circle class="node-ring" r="'+r+'"/>')+(n.type==='travel'?'<circle class="travel-glyph" r="2.5"/>':'<g class="glyph">'+glyph(f,n.type==='small'?.57:n.type==='notable'?1.05:1.3)+'</g>')+'</g>';}).join('');
  document.querySelectorAll('[data-node]').forEach(el=>{const id=el.dataset.node;this.nodes.set(id,el);el.onmouseenter=e=>this.tooltip(id,e);el.onmousemove=e=>this.moveTooltip(e);el.onmouseleave=()=>this.hideTooltip();el.onfocus=()=>this.tooltip(id,null,el);el.onblur=()=>this.hideTooltip();el.onclick=e=>{e.stopPropagation?.();if(Date.now()<(this.ignoreClickUntil||0))return;this.select(id);};el.ondblclick=e=>{e.preventDefault();this.select(id);this.edit(id);};el.oncontextmenu=e=>{e.preventDefault();this.select(id);if(this.draft.has(id))this.edit(id);};el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();this.select(id);}if(e.key==='Escape')this.hideTooltip();};});
  this.lines=Array.from(document.querySelectorAll('[data-edge]'));
 }
 bind(){
  $('testLevel').onchange=()=>{const next=Number($('testLevel').value);if(!M.valid(this.draft,next)||!M.valid(this.applied,next)){this.message('Use nível de 1 a 99 com pontos suficientes para a distribuição atual.');$('testLevel').value=String(this.level);return;}this.level=next;this.save();this.paint();};
  $('search').oninput=()=>this.filter();$('family').onchange=()=>this.filter();
  for(const [id,tab]of[['nodeTab','node'],['totalsTab','totals'],['catalogTab','catalog']])$(id).onclick=()=>{this.tab=tab;this.detail();};
  $('cancel').onclick=()=>{this.draft=new Set(this.applied);this.paint();this.message('Prévia cancelada. Seus pontos aplicados foram preservados.');};
  $('apply').onclick=()=>{if(!M.valid(this.draft,this.level)||!difference(this.draft,this.applied))return;this.applied=new Set(this.draft);const saved=this.save();this.paint();this.message(saved?'Distribuição aplicada e salva.':'Distribuição aplicada. Exporte para guardar o estudo.');};
  $('clear').onclick=()=>{if(!this.draft.size&&!this.applied.size)return;if(!window.confirm('Limpar a distribuição deste estudo? O personagem do jogo não será alterado.'))return;this.applied=new Set();this.draft=new Set();this.save();this.paint();this.message('Estudo limpo. Escolha um novo caminho.');};
  $('export').onclick=()=>{const blob=new Blob([JSON.stringify(M.snapshot(this.level,this.applied),null,2)],{type:'application/json'}),a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='Mythos_Arvore_Estudo.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);this.message('Exportado apenas o estudo aplicado. A prévia permanece nesta janela.');};
  $('import').onclick=()=>$('buildFile').click();$('buildFile').onchange=async e=>{const file=e.target.files?.[0];if(!file)return;try{if(file.size>100000)throw Error('Arquivo muito grande.');const loaded=M.validateSave(JSON.parse(await file.text()));this.level=loaded.level;this.applied=loaded.nodes;this.draft=new Set(loaded.nodes);$('testLevel').value=String(this.level);this.save();this.paint();this.message('Estudo importado.');}catch(error){this.message('Não foi possível importar: '+error.message);}e.target.value='';};
  $('zoomIn').onclick=()=>this.zoom(.8);$('zoomOut').onclick=()=>this.zoom(1.25);$('fit').onclick=()=>this.fit();$('center').onclick=()=>this.center();$('origin').onclick=()=>this.select('root');$('origin').onkeydown=e=>{if(e.key==='Enter'){this.select('root');e.preventDefault();}};
  const svg=$('tree');svg.addEventListener('wheel',e=>{e.preventDefault();this.hideTooltip();this.zoom(Math.exp(e.deltaY*.0013),e);},{passive:false});
  svg.onpointerdown=e=>{if(e.button!==0||this.nodeFrom(e.target))return;this.hideTooltip();this.drag={x:e.clientX,y:e.clientY,view:{...this.view},moved:false};svg.setPointerCapture?.(e.pointerId);svg.classList.add('dragging');};
  svg.onpointermove=e=>{if(!this.drag)return;const r=this.rect(),dx=e.clientX-this.drag.x,dy=e.clientY-this.drag.y;if(Math.hypot(dx,dy)>4)this.drag.moved=true;this.view.x=this.drag.view.x-dx/r.width*this.view.w;this.view.y=this.drag.view.y-dy/r.height*this.view.h;this.applyView();};
  const end=()=>{if(this.drag?.moved)this.ignoreClickUntil=Date.now()+150;this.drag=null;svg.classList.remove('dragging');};svg.onpointerup=end;svg.onpointercancel=end;svg.onlostpointercapture=end;
  svg.onkeydown=e=>{if(this.nodeFrom(e.target))return;const step=this.view.w*.08;if(['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','+','-','Home','Escape'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft')this.view.x-=step;if(e.key==='ArrowRight')this.view.x+=step;if(e.key==='ArrowUp')this.view.y-=step;if(e.key==='ArrowDown')this.view.y+=step;if(e.key==='+')this.zoom(.8);if(e.key==='-')this.zoom(1.25);if(e.key==='Home')this.center();if(e.key==='Escape')this.hideTooltip();this.applyView();};
  window.addEventListener('resize',()=>{const cx=this.view.x+this.view.w/2,cy=this.view.y+this.view.h/2;this.view.h=this.view.w/this.ratio();this.view.x=cx-this.view.w/2;this.view.y=cy-this.view.h/2;this.applyView();this.hideTooltip();});
 }
 nodeFrom(target){while(target&&target!==$('tree')){if(target.dataset?.node)return target.dataset.node;target=target.parentElement;}return null;}
 message(text){$('status').textContent=text;}
 select(id){if(!T.index.has(id))return;this.selected=id;this.tab='node';this.paint();}
 edit(id){if(id==='root')return;let next;if(this.draft.has(id)){next=M.remove(this.draft,id,this.level);if(!next){this.message('Este ponto conecta outros pontos. Remova primeiro as extremidades do caminho.');return;}}else{const path=M.pathTo(this.draft,id);next=M.addPath(this.draft,path,this.level);if(!next){this.message('Pontos insuficientes para este caminho. Aumente o nível de teste ou escolha uma rota menor.');return;}}this.draft=next;this.paint();this.message('Prévia atualizada. Aplicar confirma; Cancelar descarta os ajustes.');}
 paint(){
  const remaining=M.budget(this.level)-this.draft.size,added=[...this.draft].filter(id=>!this.applied.has(id)).length,removed=[...this.applied].filter(id=>!this.draft.has(id)).length;this.route=M.pathTo(this.draft,this.selected);const routeSet=new Set(this.route),routeEdges=new Set();let prev=this.route.length?T.index.get(this.route[0]).neighbors.find(id=>id==='root'||this.draft.has(id)):null;for(const id of this.route){if(prev)routeEdges.add([prev,id].sort().join('|'));prev=id;}
  $('remaining').textContent=String(remaining);$('allocated').textContent=this.applied.size+' / 98';$('pending').textContent=added||removed?'+'+added+' / −'+removed:'0';const dirty=difference(this.draft,this.applied);$('cancel').disabled=!dirty;$('apply').disabled=!dirty;
  for(const [id,el]of this.nodes){const n=T.index.get(id);el.classList.toggle('learned',this.applied.has(id)&&this.draft.has(id));el.classList.toggle('preview',this.draft.has(id)&&!this.applied.has(id));el.classList.toggle('removed',this.applied.has(id)&&!this.draft.has(id));el.classList.toggle('available',!this.draft.has(id)&&remaining>0&&n.neighbors.some(id=>id==='root'||this.draft.has(id)));el.classList.toggle('selected',this.selected===id);el.classList.toggle('dim',this.filtered&&!this.matches.has(id));el.classList.toggle('match',this.filtered&&this.matches.has(id));el.setAttribute('aria-pressed',this.draft.has(id)?'true':'false');el.setAttribute('tabindex',this.selected===id?'0':'-1');}
  this.lines.forEach((el,i)=>{const [a,b]=T.edges[i],hasA=a==='root'||this.draft.has(a),hasB=b==='root'||this.draft.has(b);el.classList.toggle('learned',hasA&&hasB&&(a==='root'||this.applied.has(a))&&(b==='root'||this.applied.has(b)));el.classList.toggle('preview',hasA&&hasB&&!( (a==='root'||this.applied.has(a))&&(b==='root'||this.applied.has(b))));el.classList.toggle('route',routeEdges.has([a,b].sort().join('|')));});
  this.detail();if(!this.storage)$('saveState').textContent='Use Exportar para guardar o estudo';
 }
 filter(){const q=$('search').value,f=$('family').value;this.filtered=!!q.trim()||f!=='all';this.matches=this.filtered?M.search(q,f):new Set();$('searchCount').textContent=this.filtered?this.matches.size+' encontrados':'';this.paint();}
 detail(){
  for(const [id,tab]of[['nodeTab','node'],['totalsTab','totals'],['catalogTab','catalog']])$(id).setAttribute('aria-selected',this.tab===tab?'true':'false');const body=$('detailBody');
  if(this.tab==='totals'){const values=M.totals(this.draft);body.innerHTML='<h2 class="summary-heading">Sua distribuição</h2><p class="section-caption">Totais da prévia. Pontos percentuais são somados; aumentos percentuais do mesmo tipo também. Condições de armas e escudo continuam necessárias.</p>'+(Object.keys(values).length?Object.keys(values).sort((a,b)=>T.MODS[a].label.localeCompare(T.MODS[b].label,'pt-BR')).map(k=>'<div class="summary-row '+(values[k]<0?'negative':'')+'"><span>'+esc(T.MODS[k].label)+'</span><b>'+(values[k]>=0?'+':'−')+Math.abs(values[k]).toLocaleString('pt-BR')+(T.MODS[k].unit==='pp'?' p.p.':T.MODS[k].unit==='percent'?'%':'')+'</b></div>').join(''):'<p class="intro-copy">Nenhuma passiva selecionada.</p>')+'<p class="section-caption">Esta janela soma modificadores de passivas, não calcula o dano final de equipamentos ou técnicas.</p>';return;}
  if(this.tab==='catalog'){body.innerHTML='<h2 class="summary-heading">Todas as passivas</h2><p class="section-caption">'+(T.nodes.length-1)+' pontos disponíveis para leitura. Abra uma afinidade e selecione qualquer ponto para ler e localizar seus efeitos na árvore.</p>'+T.families.map(f=>'<details class="catalog-group"><summary>'+esc(f.name)+'</summary>'+T.nodes.filter(n=>n.family===f.key&&n.id!=='root').map(n=>'<button class="catalog-node" data-catalog="'+n.id+'">'+esc(n.title)+'<small>'+T.lines(n).map(esc).join('<br>')+'</small></button>').join('')+'</details>').join('');document.querySelectorAll('[data-catalog]').forEach(el=>el.onclick=()=>{const id=el.dataset.catalog;this.select(id);this.focusNode(id);});return;}
  const n=T.index.get(this.selected);if(n.id==='root'){body.innerHTML='<div class="detail-crest" style="--color:#d6bb7e"><svg viewBox="-16 -16 32 32">'+glyph(T.families[6])+'</svg></div><h2>Seu próprio caminho</h2><p class="detail-type">Guardião · origem da árvore</p><div class="intro-copy"><p>O Guardião é o único personagem representado no centro. Todos os caminhos ao redor podem fazer parte da sua build.</p><h3>Leia antes de escolher</h3><p>Passe o mouse sobre qualquer ponto: o título e cada bônus aparecem na janela flutuante.</p><p>Clique para examinar. Adicione um ponto ou o caminho conectado pela lateral. Duplo clique também adiciona; clique direito tenta remover da prévia.</p><p>Você nasce sem pontos passivos. Cada novo nível concede um ponto, até 98 no nível 99.</p></div>';return;}
  const f=T.families.find(f=>f.key===n.family),allocated=this.draft.has(n.id),path=this.route,type={travel:'Passiva de passagem',small:'Passiva menor',notable:'Passiva notável',keystone:'Escolha maior'}[n.type];
  body.innerHTML='<div class="detail-crest" style="--color:'+f.color+'"><svg viewBox="-16 -16 32 32">'+glyph(f)+'</svg></div><h2>'+esc(n.title)+'</h2><p class="detail-type">'+type+' · '+esc(f.name)+'</p><div class="detail-bonuses">'+Object.entries(n.mods).map(([k,v])=>'<p class="'+(v<0?'penalty':'')+'">'+esc(T.text(k,v))+'</p>').join('')+'</div><p class="detail-cost">Custo do ponto: 1</p><p class="detail-description">'+(n.type==='keystone'?'Uma escolha de build com benefício e contrapartida.':n.group?'Especialização: '+esc(n.group)+'.':'Um passo que fortalece e conecta sua distribuição.')+'</p><p class="selected-path">'+(allocated?(this.applied.has(n.id)?'Aprendido no estudo aplicado.':'Adicionado à prévia.'):(path.length===1?'Conectado ao seu caminho.':path.length?'Caminho até este ponto: '+path.length+' pontos.':'Não foi encontrada uma conexão.'))+'</p><button id="editPassive" class="detail-action" '+(!allocated&&(path.length<1||path.length>M.budget(this.level)-this.draft.size)?'disabled':'')+'>'+(allocated?'Remover da prévia':path.length===1?'Adicionar 1 ponto':'Adicionar caminho · '+path.length)+'</button><p class="section-caption">Remover um ponto não pode desconectar outros. Aplicar confirma toda a distribuição; Cancelar retorna ao estudo aplicado.</p>';$('editPassive').onclick=()=>this.edit(n.id);
 }
 tooltip(id,event,element){const n=T.index.get(id);if(!n)return;$('tooltipTitle').textContent=n.title;$('tooltipStats').innerHTML=Object.entries(n.mods).map(([k,v])=>'<p class="'+(v<0?'penalty':'')+'">'+esc(T.text(k,v))+'</p>').join('');$('tooltipFooter').textContent=(n.type==='keystone'?'Escolha maior':n.type==='notable'?'Passiva notável':n.type==='travel'?'Passiva de passagem':'Passiva menor')+' · 1 ponto';$('treeTooltip').hidden=false;if(event)this.moveTooltip(event);else{const r=element?.getBoundingClientRect?.()||{left:100,top:100,width:20,height:20};this.moveTooltip({clientX:r.left+r.width/2,clientY:r.top+r.height});}}
 moveTooltip(e){const box=$('treeTooltip');if(box.hidden)return;const w=box.offsetWidth||355,h=box.offsetHeight||150;let x=e.clientX+17,y=e.clientY+17;if(x+w>innerWidth-12)x=e.clientX-w-17;if(y+h>innerHeight-12)y=e.clientY-h-17;box.style.left=Math.max(10,Math.min(innerWidth-w-10,x))+'px';box.style.top=Math.max(10,Math.min(innerHeight-h-10,y))+'px';}
 hideTooltip(){$('treeTooltip').hidden=true;}
 rect(){const r=$('tree').getBoundingClientRect?.();return r?.width&&r?.height?r:{left:0,top:0,width:900,height:600};}
 ratio(){const r=this.rect();return r.width/r.height;}
 applyView(){this.view.x=Math.max(-3000,Math.min(3000,this.view.x+this.view.w/2))-this.view.w/2;this.view.y=Math.max(-3000,Math.min(3000,this.view.y+this.view.h/2))-this.view.h/2;$('tree').setAttribute('viewBox',[this.view.x,this.view.y,this.view.w,this.view.h].join(' '));$('zoomLabel').textContent=Math.round(2200/this.view.w*100)+'%';}
 center(){this.view.w=2200;this.view.h=this.view.w/this.ratio();this.view.x=-this.view.w/2;this.view.y=-this.view.h/2;this.applyView();}
 fit(){this.view.h=Math.max(4100,4100/this.ratio());this.view.w=this.view.h*this.ratio();this.view.x=-this.view.w/2;this.view.y=-this.view.h/2;this.applyView();}
 focusNode(id){const n=T.index.get(id);this.view.w=1250;this.view.h=this.view.w/this.ratio();this.view.x=n.x-this.view.w/2;this.view.y=n.y-this.view.h/2;this.applyView();this.nodes.get(id)?.focus();}
 zoom(factor,event){const r=this.rect(),rx=event?Math.max(0,Math.min(1,(event.clientX-r.left)/r.width)):.5,ry=event?Math.max(0,Math.min(1,(event.clientY-r.top)/r.height)):.5,wx=this.view.x+this.view.w*rx,wy=this.view.y+this.view.h*ry,next=Math.max(500,Math.min(8500,this.view.w*factor));this.view.w=next;this.view.h=next/this.ratio();this.view.x=wx-next*rx;this.view.y=wy-this.view.h*ry;this.applyView();}
}
window.mythosTree=new PassiveStudy();
})();
